"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");

const { handleRequest } = require("../src/app");

function createRes() {
  return {
    statusCode: 200,
    headers: {},
    body: "",
    headersSent: false,
    writableEnded: false,
    setHeader(name, value) {
      this.headers[name.toLowerCase()] = value;
    },
    end(chunk) {
      this.body += chunk === undefined || chunk === null ? "" : String(chunk);
      this.headersSent = true;
      this.writableEnded = true;
    },
  };
}

function callHandleRequest(method, url) {
  const req = { method, url };
  const res = createRes();
  handleRequest(req, res);
  return res;
}

test("GET /healthz returns 200 JSON status ok", () => {
  const res = callHandleRequest("GET", "/healthz");

  assert.equal(res.statusCode, 200);
  assert.match(res.headers["content-type"], /application\/json/);
  assert.equal(res.body, '{"status":"ok"}');
});

test("GET /no-such-path returns 404 not_found", () => {
  const res = callHandleRequest("GET", "/no-such-path");

  assert.equal(res.statusCode, 404);
  assert.match(res.headers["content-type"], /application\/json/);
  assert.equal(res.body, '{"error":"not_found"}');
});

test("POST /healthz is treated as unregistered path", () => {
  const res = callHandleRequest("POST", "/healthz");

  assert.equal(res.statusCode, 404);
  assert.equal(res.body, '{"error":"not_found"}');
});

test("handler exception returns 500 internal_error and process keeps serving", () => {
  const res = createRes();
  const req = {
    method: "GET",
    get url() {
      throw new Error("injected failure for /boom");
    },
  };

  handleRequest(req, res);

  assert.equal(res.statusCode, 500);
  assert.match(res.headers["content-type"], /application\/json/);
  assert.equal(res.body, '{"error":"internal_error"}');

  const healthz = callHandleRequest("GET", "/healthz");
  assert.equal(healthz.statusCode, 200);
  assert.equal(healthz.body, '{"status":"ok"}');
});

